//! NCBI genetic code tables and the synonymous families derived from them.
//!
//! Ticket P1-05. Data: `crates/cf-types/data/genetic_codes.json`, generated by
//! `tools/generate_genetic_codes.py` from Biopython's vendored NCBI tables.
//!
//! PLAN CORRECTION (P1-05). The ticket says "all 33 NCBI translation tables".
//! NCBI defines 27 tables in the id range 1..=33; ids 7, 8, 17, 18, 19 and 20
//! are retired and have no assignment. `translation_table` is therefore
//! validated against the *defined* set, not against the range, and requesting
//! id 7 fails with `CF-SEQ-007` rather than silently falling back.
//!
//! PLAN CORRECTION (synonymous family size). Several planning documents state
//! the synonymous family size as "1-6". That holds for the standard and
//! bacterial tables, but table 14 (Alternative Flatworm Mitochondrial) has an
//! 8-member serine family. Nothing here assumes an upper bound: families are
//! stored flattened with per-codon offsets, so the true maximum is a property
//! of the data rather than a compile-time constant.

use std::collections::BTreeMap;
use std::sync::OnceLock;

use crate::codon::{Codon, CODON_COUNT};
use crate::error::{code, CfError, Result};

const RAW: &str = include_str!("../data/genetic_codes.json");

/// One NCBI translation table, with its synonymous families precomputed.
///
/// `Debug` is deliberately terse: printing 64 codon assignments plus the
/// flattened families into an assertion failure buries the actual failure.
pub struct GeneticCode {
    id: u8,
    name: String,
    aliases: Vec<String>,
    /// Amino acid per codon index; `b'*'` for stop.
    aa: [u8; CODON_COUNT],
    is_start: [bool; CODON_COUNT],
    is_stop: [bool; CODON_COUNT],
    /// Synonymous families, flattened so a lookup is a slice of `family_flat`.
    family_offset: [u16; CODON_COUNT],
    family_len: [u8; CODON_COUNT],
    family_flat: Vec<Codon>,
    max_family_len: u8,
}

impl GeneticCode {
    pub fn id(&self) -> u8 {
        self.id
    }
    pub fn name(&self) -> &str {
        &self.name
    }
    pub fn aliases(&self) -> &[String] {
        &self.aliases
    }

    /// Amino acid for a codon, as an ASCII byte; `b'*'` for a stop codon.
    #[inline]
    pub fn amino_acid(&self, codon: Codon) -> u8 {
        self.aa[codon.index_usize()]
    }

    #[inline]
    pub fn is_stop(&self, codon: Codon) -> bool {
        self.is_stop[codon.index_usize()]
    }

    #[inline]
    pub fn is_start(&self, codon: Codon) -> bool {
        self.is_start[codon.index_usize()]
    }

    /// Every codon encoding the same amino acid, including `codon` itself.
    ///
    /// This is the hot-path lookup for every mutation and every delta-table
    /// expansion, so it is a slice into a flat array rather than a map lookup.
    #[inline]
    pub fn synonyms(&self, codon: Codon) -> &[Codon] {
        let start = self.family_offset[codon.index_usize()] as usize;
        let len = self.family_len[codon.index_usize()] as usize;
        &self.family_flat[start..start + len]
    }

    /// Whether two codons encode the same amino acid.
    ///
    /// The precondition `CodonSequence::substitute` enforces, and therefore the
    /// single place protein invariance is decided.
    #[inline]
    pub fn are_synonymous(&self, a: Codon, b: Codon) -> bool {
        self.aa[a.index_usize()] == self.aa[b.index_usize()]
    }

    /// Largest synonymous family in this table. A property of the data.
    pub fn max_family_len(&self) -> u8 {
        self.max_family_len
    }

    /// Mean synonymous family size over the codons actually used by `codons`.
    /// This is the `S` of the complexity analyses.
    pub fn mean_family_size(&self, codons: &[Codon]) -> f64 {
        if codons.is_empty() {
            return 0.0;
        }
        let total: usize = codons.iter().map(|c| self.synonyms(*c).len()).sum();
        total as f64 / codons.len() as f64
    }

    pub fn translate(&self, codons: &[Codon]) -> Vec<u8> {
        codons.iter().map(|c| self.amino_acid(*c)).collect()
    }

    /// Look up a table by NCBI id.
    pub fn get(id: u8) -> Result<&'static GeneticCode> {
        tables().get(&id).ok_or_else(|| {
            CfError::new(
                code::SEQ_UNKNOWN_TABLE,
                format!(
                    "NCBI translation table {id} is not defined; defined ids are {:?}",
                    defined_ids()
                ),
            )
        })
    }
}

impl std::fmt::Debug for GeneticCode {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(
            f,
            "GeneticCode({} {:?}, max family {})",
            self.id, self.name, self.max_family_len
        )
    }
}

fn tables() -> &'static BTreeMap<u8, GeneticCode> {
    static TABLES: OnceLock<BTreeMap<u8, GeneticCode>> = OnceLock::new();
    TABLES.get_or_init(load)
}

/// The NCBI table ids that actually exist.
pub fn defined_ids() -> Vec<u8> {
    tables().keys().copied().collect()
}

fn load() -> BTreeMap<u8, GeneticCode> {
    // A parse failure here is a corrupted vendored asset, not a user error, so
    // it panics with an actionable message rather than propagating a Result
    // through every call site.
    let doc: serde_json::Value = serde_json::from_str(RAW).expect(
        "genetic_codes.json is malformed; regenerate it with tools/generate_genetic_codes.py",
    );

    let raw_tables = doc["tables"]
        .as_object()
        .expect("genetic_codes.json has no `tables` object");

    let mut out = BTreeMap::new();
    for (key, value) in raw_tables {
        let id: u8 = key.parse().expect("table id must be numeric");
        let aa_str = value["aa"].as_str().expect("table has no `aa` string");
        assert_eq!(
            aa_str.len(),
            CODON_COUNT,
            "table {id}: `aa` must have exactly 64 entries"
        );

        let mut aa = [0u8; CODON_COUNT];
        for (i, byte) in aa_str.bytes().enumerate() {
            aa[i] = byte;
        }

        let mut is_start = [false; CODON_COUNT];
        for start in value["starts"].as_array().expect("`starts`") {
            let codon = Codon::parse(start.as_str().expect("codon string"))
                .expect("start codon must be a valid codon");
            is_start[codon.index_usize()] = true;
        }

        let mut is_stop = [false; CODON_COUNT];
        for stop in value["stops"].as_array().expect("`stops`") {
            let codon = Codon::parse(stop.as_str().expect("codon string"))
                .expect("stop codon must be a valid codon");
            is_stop[codon.index_usize()] = true;
        }
        // Cross-check: the declared stop set must agree with the `aa` string.
        for (i, (&stop, &residue)) in is_stop.iter().zip(aa.iter()).enumerate() {
            assert_eq!(
                stop,
                residue == b'*',
                "table {id}: stop set disagrees with `aa` at codon index {i}"
            );
        }

        // Flatten synonymous families, grouped by amino acid in index order so
        // that the layout is deterministic across runs and platforms.
        let mut family_offset = [0u16; CODON_COUNT];
        let mut family_len = [0u8; CODON_COUNT];
        let mut family_flat: Vec<Codon> = Vec::with_capacity(CODON_COUNT);
        let mut by_aa: BTreeMap<u8, Vec<Codon>> = BTreeMap::new();
        for (i, &residue) in aa.iter().enumerate() {
            by_aa
                .entry(residue)
                .or_default()
                .push(Codon::from_index_unchecked(i as u8));
        }
        let mut max_family_len = 0u8;
        for members in by_aa.values() {
            let offset = family_flat.len() as u16;
            let len = members.len() as u8;
            max_family_len = max_family_len.max(len);
            for codon in members {
                family_offset[codon.index_usize()] = offset;
                family_len[codon.index_usize()] = len;
            }
            family_flat.extend_from_slice(members);
        }
        assert_eq!(family_flat.len(), CODON_COUNT);

        out.insert(
            id,
            GeneticCode {
                id,
                name: value["name"].as_str().unwrap_or_default().to_string(),
                aliases: value["aliases"]
                    .as_array()
                    .map(|a| {
                        a.iter()
                            .filter_map(|v| v.as_str().map(str::to_string))
                            .collect()
                    })
                    .unwrap_or_default(),
                aa,
                is_start,
                is_stop,
                family_offset,
                family_len,
                family_flat,
                max_family_len,
            },
        );
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    /// TST-CORE-002: the vendored tables match NCBI, independently of Biopython.
    ///
    /// The spot checks below are transcribed from the NCBI genetic code
    /// definitions rather than re-derived from the generator's own source, so a
    /// Biopython upgrade that changed a table would fail here.
    #[test]
    fn unit_tst_core_002_vendored_tables_match_ncbi() {
        let ids = defined_ids();
        assert_eq!(
            ids.len(),
            27,
            "expected 27 defined NCBI tables, got {}",
            ids.len()
        );
        for gap in [7u8, 8, 17, 18, 19, 20] {
            assert!(!ids.contains(&gap), "id {gap} should be undefined");
            assert_eq!(
                GeneticCode::get(gap).unwrap_err().code,
                code::SEQ_UNKNOWN_TABLE
            );
        }

        // Table 1, Standard.
        let t1 = GeneticCode::get(1).unwrap();
        assert_eq!(t1.amino_acid(Codon::parse("ATG").unwrap()), b'M');
        assert_eq!(t1.amino_acid(Codon::parse("TGG").unwrap()), b'W');
        for stop in ["TAA", "TAG", "TGA"] {
            assert!(
                t1.is_stop(Codon::parse(stop).unwrap()),
                "{stop} should stop in table 1"
            );
        }
        assert_eq!(t1.amino_acid(Codon::parse("AGA").unwrap()), b'R');

        // Table 2, Vertebrate Mitochondrial: AGA/AGG are stops, ATA is Met,
        // TGA is Trp. These four differences are the table's whole point.
        let t2 = GeneticCode::get(2).unwrap();
        assert!(t2.is_stop(Codon::parse("AGA").unwrap()));
        assert!(t2.is_stop(Codon::parse("AGG").unwrap()));
        assert_eq!(t2.amino_acid(Codon::parse("ATA").unwrap()), b'M');
        assert_eq!(t2.amino_acid(Codon::parse("TGA").unwrap()), b'W');

        // Table 6, Ciliate: TAA and TAG encode glutamine.
        let t6 = GeneticCode::get(6).unwrap();
        assert_eq!(t6.amino_acid(Codon::parse("TAA").unwrap()), b'Q');
        assert_eq!(t6.amino_acid(Codon::parse("TAG").unwrap()), b'Q');
        assert!(t6.is_stop(Codon::parse("TGA").unwrap()));

        // Table 11, Bacterial: same code as Standard, different start codons.
        let t11 = GeneticCode::get(11).unwrap();
        for i in 0..CODON_COUNT as u8 {
            let c = Codon::from_index(i).unwrap();
            assert_eq!(
                t11.amino_acid(c),
                t1.amino_acid(c),
                "table 11 should share table 1's assignments at {c}"
            );
        }
        for start in ["ATG", "GTG", "TTG"] {
            assert!(
                t11.is_start(Codon::parse(start).unwrap()),
                "{start} is a bacterial start"
            );
        }
    }

    #[test]
    fn unit_synonymous_families_are_consistent() {
        for id in defined_ids() {
            let table = GeneticCode::get(id).unwrap();
            let mut covered = 0usize;
            for codon in Codon::all() {
                let family = table.synonyms(codon);
                assert!(
                    family.contains(&codon),
                    "table {id}: {codon} missing from its own family"
                );
                for member in family {
                    assert!(
                        table.are_synonymous(codon, *member),
                        "table {id}: {codon} and {member} in one family but not synonymous"
                    );
                }
                // Family membership is exactly "same amino acid".
                let expected = Codon::all()
                    .filter(|c| table.amino_acid(*c) == table.amino_acid(codon))
                    .count();
                assert_eq!(
                    family.len(),
                    expected,
                    "table {id}: wrong family size at {codon}"
                );
                covered += 1;
            }
            assert_eq!(covered, CODON_COUNT);
        }
    }

    /// The documented "1-6" family bound is wrong; record the real maximum.
    #[test]
    fn unit_max_family_size_is_eight_not_six() {
        let t14 = GeneticCode::get(14).unwrap();
        assert_eq!(
            t14.max_family_len(),
            8,
            "table 14 has an 8-member serine family; nothing may assume a bound of 6"
        );
        let t11 = GeneticCode::get(11).unwrap();
        assert_eq!(t11.max_family_len(), 6, "bacterial table maxes out at 6");
        let overall = defined_ids()
            .into_iter()
            .map(|id| GeneticCode::get(id).unwrap().max_family_len())
            .max()
            .unwrap();
        assert_eq!(overall, 8);
    }

    #[test]
    fn unit_mean_family_size_matches_the_complexity_analyses() {
        // The complexity analyses use S ~ 2.9 for a typical protein. Check the
        // figure is in the right neighbourhood for a real bacterial CDS rather
        // than taking it on faith.
        let t11 = GeneticCode::get(11).unwrap();
        let cds = "ATGAAACGTATTCTGGATGAAGGCGCAACCGTTAGCCTGTAA";
        let codons: Vec<Codon> = cds
            .as_bytes()
            .chunks(3)
            .map(|c| Codon::from_bytes(c).unwrap())
            .collect();
        let mean = t11.mean_family_size(&codons);
        assert!(
            (2.0..5.0).contains(&mean),
            "mean synonymous family size {mean} is implausible"
        );
    }
}
